package io.tradeops.importer; import io.tradeops.web.CorrelationIdFilter; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.MediaType;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/imports") public class TransactionImportController{private final TransactionImportService service;public TransactionImportController(TransactionImportService s){service=s;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public TransactionImportService.Summary upload(@RequestPart("file") MultipartFile file,Authentication auth,HttpServletRequest req)throws Exception{return service.importCsv(file.getOriginalFilename()==null?"upload.csv":file.getOriginalFilename(),file.getBytes(),auth.getName(),req.getAttribute(CorrelationIdFilter.REQUEST_ATTRIBUTE).toString());}}